-- ============================================================
-- Mundo de Artanis -- Itens
-- Tabela de itens e seed gerado a partir do ItemDatabase.json (385 itens)
-- Seguro para reexecutar. Arquivo 100% ASCII (acentos como hex).
-- O elemento gelo nao existe no jogo: foi convertido para agua.
-- ============================================================

USE artanis_planner;

CREATE TABLE IF NOT EXISTS items (
    id           INT PRIMARY KEY,
    name         VARCHAR(120) NOT NULL,
    type         VARCHAR(30) NOT NULL,
    subcategory  VARCHAR(50),
    tier         INT DEFAULT 0,
    buy_price    INT DEFAULT 0,
    sell_price   INT DEFAULT 0,
    attributes   JSON,
    lore         TEXT
) ENGINE=InnoDB;

ON DUPLICATE KEY UPDATE
  name=VALUES(name), type=VALUES(type), subcategory=VALUES(subcategory), tier=VALUES(tier),
  buy_price=VALUES(buy_price), sell_price=VALUES(sell_price),
  attributes=VALUES(attributes), lore=VALUES(lore);
